/* Service worker. Generated by scripts/build-sw.mjs: do not edit the copy in out/. */
const VERSION = "__VERSION__";
const STATIC_FILES = __STATIC_FILES__;
const SHELL_FILES = __SHELL_FILES__;
const AUDIO_BASE = "https://everyayah.com/data/";

const SHELL = `noor-shell-${VERSION}`;
const STATIC = "noor-static"; // hashed files never change, so old ones stay usable by saved pages
const PAGES = "noor-pages"; // whatever was visited
const OFFLINE = "noor-quran-offline"; // saved on request, kept across updates
const AUDIO = "noor-audio"; // saved on request, kept across updates
const PAGES_LIMIT = 200;
const SLOW_MS = 6000;

/** Weak mobile networks drop connections, so each file gets a few tries, a few files at a time. */
async function keep(cache, urls, init) {
  for (let i = 0; i < urls.length; i += 4) {
    await Promise.all(urls.slice(i, i + 4).map(async (url) => {
      for (let attempt = 1; ; attempt++) {
        try {
          return await cache.add(new Request(url, init));
        } catch (error) {
          if (attempt === 4) throw error;
          await new Promise((resolve) => setTimeout(resolve, attempt * 500));
        }
      }
    }));
  }
}

self.addEventListener("install", (event) => {
  event.waitUntil((async () => {
    const assets = await caches.open(STATIC);
    const missing = [];
    for (const url of STATIC_FILES) if (!(await assets.match(url))) missing.push(url);
    await keep(assets, missing);
    await keep(await caches.open(SHELL), SHELL_FILES, { cache: "reload" });
  })());
});

self.addEventListener("activate", (event) => {
  event.waitUntil((async () => {
    for (const name of await caches.keys()) {
      if ((name.startsWith("noor-shell-") && name !== SHELL) || name === PAGES) await caches.delete(name);
    }
    await self.clients.claim();
  })());
});

// An update waits until the visitor accepts it, so a page is never swapped underneath them.
self.addEventListener("message", (event) => {
  if (event.data === "skip-waiting") self.skipWaiting();
});

/** Safari asks for audio in pieces, so a saved file has to answer byte ranges. */
async function rangeResponse(response, rangeHeader) {
  const blob = await response.blob();
  const type = response.headers.get("Content-Type") || "audio/mpeg";
  const match = /^bytes=(\d*)-(\d*)$/.exec(rangeHeader || "");
  if (!match || (!match[1] && !match[2])) {
    return new Response(blob, { status: 200, headers: { "Content-Type": type, "Content-Length": String(blob.size), "Accept-Ranges": "bytes" } });
  }
  let start = match[1] ? Number(match[1]) : Math.max(0, blob.size - Number(match[2]));
  const end = match[1] && match[2] ? Math.min(Number(match[2]), blob.size - 1) : blob.size - 1;
  if (start >= blob.size || start > end) {
    return new Response(null, { status: 416, headers: { "Content-Range": `bytes */${blob.size}` } });
  }
  return new Response(blob.slice(start, end + 1), {
    status: 206,
    headers: { "Content-Type": type, "Content-Length": String(end - start + 1), "Content-Range": `bytes ${start}-${end}/${blob.size}`, "Accept-Ranges": "bytes" },
  });
}

async function audio(request) {
  const saved = await (await caches.open(AUDIO)).match(request.url);
  return saved ? rangeResponse(saved, request.headers.get("Range")) : fetch(request);
}

/**
 * A worker script takes its address from the response. The search worker is started with its
 * settings after "#" in that address, which a fetched or cached response no longer has.
 * A rebuilt response has no address of its own, so the requested one (with "#...") is kept.
 */
function forDestination(request, response) {
  if (request.destination !== "worker" && request.destination !== "sharedworker") return response;
  return new Response(response.body, { status: response.status, statusText: response.statusText, headers: response.headers });
}

async function cacheFirst(request) {
  const hit = await caches.match(request, { ignoreSearch: true });
  if (hit) return forDestination(request, hit);
  const response = await fetch(request);
  if (response.ok) await (await caches.open(STATIC)).put(request, response.clone());
  return forDestination(request, response);
}

async function savedCopy(key) {
  for (const name of [SHELL, OFFLINE, PAGES]) {
    const hit = await (await caches.open(name)).match(key, { ignoreSearch: true });
    if (hit) return hit;
  }
  return null;
}

async function remember(key, response) {
  const offline = await caches.open(OFFLINE);
  if (await offline.match(key)) return offline.put(key, response);
  const pages = await caches.open(PAGES);
  await pages.put(key, response);
  const keys = await pages.keys();
  for (const old of keys.slice(0, Math.max(0, keys.length - PAGES_LIMIT))) await pages.delete(old);
}

/** Fresh when possible; the saved copy when offline or when the network crawls. */
async function networkFirst(event, key, isPage) {
  const saved = await savedCopy(key);
  const network = fetch(event.request).then((response) => {
    if (response.ok && !response.redirected) event.waitUntil(remember(key, response.clone()));
    return response;
  });
  try {
    if (!saved) return await network;
    const slow = new Promise((resolve) => setTimeout(() => resolve(saved.clone()), SLOW_MS));
    const response = await Promise.race([network, slow]);
    return response.status >= 500 ? saved : response;
  } catch (error) {
    if (saved) return saved;
    if (isPage) {
      const fallback = await caches.match("/no-connection.html");
      if (fallback) return fallback;
    }
    throw error;
  }
}

self.addEventListener("fetch", (event) => {
  const { request } = event;
  if (request.method !== "GET") return;
  const url = new URL(request.url);
  if (url.origin !== self.location.origin) {
    if (request.url.startsWith(AUDIO_BASE)) event.respondWith(audio(request));
    return;
  }
  if (url.pathname === "/sw.js") return;
  if (url.pathname.startsWith("/_next/static/")) return event.respondWith(cacheFirst(request));
  // Query strings (search words, router hints) do not change which file is served.
  event.respondWith(networkFirst(event, url.origin + url.pathname, request.mode === "navigate"));
});

// Tapping a prayer reminder brings the app forward.
self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  event.waitUntil(self.clients.matchAll({ type: "window", includeUncontrolled: true }).then((open) => (open[0] ? open[0].focus() : self.clients.openWindow("/"))));
});
